"""Generated by the NL to Flow Diagram Encoder Pipeline."""

class Stack:
    def __init__(self):
        self.items = []
        self.top = (-1)

    def show(self):
        stack_items = self.items
        print(f'Stack:  {stack_items}')

    def push(self, value):
        new_length = (len(self.items) + 1)
        temp = []
        for fill_index in range(0, new_length):
            temp.append(None)
        i = 0
        for x in self.items:
            temp[i] = x
            i = (i + 1)
        temp[(self.top + 1)] = value
        self.items = temp
        self.top = (self.top + 1)
        print(f'Pushed:  {value}')
        self.show()

    def pop(self):
        if self.is_empty():
            print('Pop attempted on empty stack')
            self.show()
            return None
        value = self.items[self.top]
        new_length = (len(self.items) - 1)
        temp = []
        for fill_index in range(0, new_length):
            temp.append(None)
        i = 0
        while (i < new_length):
            temp[i] = self.items[i]
            i = (i + 1)
        self.items = temp
        self.top = (self.top - 1)
        print(f'Popped:  {value}')
        self.show()
        return value

    def peek(self):
        if self.is_empty():
            print('Peek attempted on empty stack')
            self.show()
            return None
        value = self.items[self.top]
        print(f'Peeked:  {value}')
        self.show()
        return value

    def is_empty(self):
        return (self.top == (-1))

    def size(self):
        return (self.top + 1)

s = Stack()

s.push(10)

s.push(20)

s.push(30)

s.peek()

s.pop()

s.peek()

s.pop()

s.pop()

s.pop()

s.peek()
